const DEFAULT_SETTINGS = Object.freeze({ sensitivity: 1, fov: 85, masterVolume: .7, sfxVolume: .8, quality: 'high', renderScale: 1, crosshair: 'cross', shake: .5, musicVolume: .15, invertY: false, shadows: true, effects: 'high', reducedMotion: false });
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const record = v => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
const finite = (v, fallback, min, max) => typeof v === 'number' && Number.isFinite(v) ? Math.min(max, Math.max(min, v)) : fallback;
const member = (v, values, fallback) => values.includes(v) ? v : fallback;
const tint = v => typeof v === 'number' ? `#${v.toString(16).padStart(6, '0')}` : /^#[0-9a-f]{3,8}$/i.test(v || '') ? v : '#d6ff38';
const time = s => `${Math.floor(Math.max(0, s) / 60)}:${String(Math.floor(Math.max(0, s)) % 60).padStart(2, '0')}`;
const copy = value => JSON.parse(JSON.stringify(value));
const label = value => value.charAt(0).toUpperCase() + value.slice(1);
const teamLabel = team => team === 'a' ? '▲ Team A' : '◆ Team B';
