const classSymbols = { runner: '»', bulwark: '▰', medic: '+', engineer: '⚙', disruptor: '◎', acrobat: '↑' };
const controlRows = [['W A S D', 'Move'], ['MOUSE', 'Look'], ['LMB', 'Fire'], ['RMB', 'Aim / alternate fire'], ['SHIFT', 'Sprint'], ['SPACE', 'Jump'], ['C / CTRL', 'Crouch / sprint-slide'], ['R', 'Reload'], ['1 / 2', 'Switch weapons'], ['Q / E', 'Tactical / lethal'], ['F', 'Class ability'], ['X', 'Impulse pulse'], ['TAB', 'Scoreboard'], ['ESC', 'Pause / release mouse']];

function validateSettings(raw) {
  const v = record(raw);
  return { sensitivity: finite(v.sensitivity, 1, .2, 3), fov: finite(v.fov, 85, 65, 110), masterVolume: finite(v.masterVolume, .7, 0, 1), sfxVolume: finite(v.sfxVolume, .8, 0, 1), quality: member(v.quality, ['low', 'medium', 'high'], 'high'), renderScale: finite(v.renderScale, 1, .5, 1.5), crosshair: member(v.crosshair, ['cross', 'dot', 'circle'], 'cross'), shake: finite(v.shake, .5, 0, 1), musicVolume: finite(v.musicVolume, .15, 0, 1), invertY: typeof v.invertY === 'boolean' ? v.invertY : false, shadows: typeof v.shadows === 'boolean' ? v.shadows : true, effects: member(v.effects, ['low', 'medium', 'high'], 'high'), reducedMotion: typeof v.reducedMotion === 'boolean' ? v.reducedMotion : false };
}
function validateMatch(raw) {
  const v = record(raw), classes = Array.isArray(v.botClasses) ? [...new Set(v.botClasses.filter(id => Object.hasOwn(CLASSES, id)))].slice(0, 6) : [];
  return { botCount: Math.round(finite(v.botCount, 5, 0, 12)), difficulty: member(v.difficulty, ['easy', 'normal', 'hard', 'veteran'], 'normal'), duration: member(v.duration, [60, 180, 300, 600], 180), scoreLimit: member(v.scoreLimit, [10, 20, 30, 50, 100], 20), mode: member(v.mode, ['ffa', 'tdm'], 'ffa'), playerTeam: member(v.playerTeam, ['a', 'b'], 'a'), name: typeof v.name === 'string' ? v.name.replace(/[\x00-\x1f]/g, '').trim().slice(0, 16) || 'Player' : 'Player', botClasses: classes.length ? classes : Object.keys(CLASSES) };
}
function validateSaved(raw) {
  return Array.from({ length: 6 }, (_, i) => { const item = record(Array.isArray(raw) ? raw[i] : null); return item.loadout && typeof item.loadout === 'object' ? { name: typeof item.name === 'string' ? item.name.trim().slice(0, 24) || `Loadout ${i + 1}` : `Loadout ${i + 1}`, loadout: normalizeLoadout(item.loadout) } : null; });
}
